// हिन्दी (PRD §9 localisation: operator screens F4–F8 and the public verify page).
// Same keys as i18n.en.ts. Stage, field, check, option and quality-parameter labels come from the database in English
// and are translated here by key (stage.<type>, field.<key>, check.<English text>, opt.<value>, qp.<param>,
// computed.<key>). tests/i18n.test.ts fails the build if an English key or a stage-form label has no Hindi.
// Written for field staff in eastern UP: plain Hindi, common English loan words kept where they are what people say
// (QR, Excel, PDF, लॉट, बैच). A native-speaker review with operators is a Phase 3 human task.
// The words of the public verify page (and the frame around it) are in i18n.public.ts, which the public page loads
// alone; this file is the rest, loaded with the signed-in app (FIX_LIST K13).
